<style>
.budget-page{--budget-purple:#7c3aed;--budget-dark:#4c1d95;--budget-line:#e5e7eb;--budget-muted:#6b7280;color:#374151;font-family:'Nunito',system-ui,sans-serif;padding:1.5rem 0 3rem;font-size:13px}
.budget-page *{box-sizing:border-box}.budget-page h1,.budget-page h2,.budget-page h3,.budget-page p{margin-top:0}
.budget-page .budget-topbar{background:linear-gradient(135deg,#7c3aed,#4c1d95);border-radius:14px;padding:1.2rem 1.4rem;display:flex;align-items:center;justify-content:space-between;gap:1rem;flex-wrap:wrap;margin-bottom:1.25rem;color:#fff}
.budget-page .budget-topbar h1{color:#fff;font-size:17px;font-weight:700;margin:0 0 5px;display:flex;align-items:center;gap:9px}.budget-page .budget-topbar p{color:#ede9fe;font-size:12px;margin:0;max-width:620px}
.budget-page .budget-button{display:inline-flex;align-items:center;justify-content:center;gap:7px;padding:10px 15px;border:1px solid transparent;border-radius:8px;font:inherit;font-size:12px;font-weight:700;line-height:1.4;text-decoration:none;cursor:pointer;white-space:nowrap;transition:background .15s,color .15s;min-height:38px}
.budget-page .budget-button.primary{background:#7c3aed;color:#fff}.budget-page .budget-button.primary:hover{background:#6d28d9}.budget-page .budget-button.light{background:#fff;color:#4c1d95}.budget-page .budget-button.secondary{background:#f5f3ff;color:#5b21b6;border-color:#ddd6fe}.budget-page .budget-button.success{background:#059669;color:#fff}.budget-page .budget-button.danger{background:#fef2f2;color:#b91c1c;border-color:#fecaca}.budget-page .budget-button:disabled{opacity:.5;cursor:not-allowed}
.budget-page a:focus-visible,.budget-page button:focus-visible,.budget-page summary:focus-visible{outline:3px solid #c4b5fd;outline-offset:3px}
.budget-page .budget-stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px;margin-bottom:1.25rem}.budget-page .budget-stat{background:#fff;border:1px solid var(--budget-line);border-left:3px solid #7c3aed;border-radius:13px;padding:16px;box-shadow:0 1px 3px #00000008;min-width:0}.budget-page .budget-stat.green{border-left-color:#10b981}.budget-page .budget-stat.amber{border-left-color:#f59e0b}.budget-page .budget-stat.blue{border-left-color:#3b82f6}
.budget-page .budget-stat-label{color:#6b7280;font-size:10.5px;text-transform:uppercase;letter-spacing:.05em;font-weight:700;margin-bottom:8px;display:flex;align-items:center;gap:7px}.budget-page .budget-stat-value{font-size:19px;font-weight:700;line-height:1.4;color:#111827;overflow-wrap:anywhere;font-variant-numeric:tabular-nums}.budget-page .budget-stat-sub{font-size:11px;color:#6b7280;margin-top:5px}
.budget-page .budget-card{background:#fff;border:1px solid var(--budget-line);border-radius:14px;box-shadow:0 1px 4px #00000008;overflow:hidden;margin-bottom:1.25rem}.budget-page .budget-card-header{padding:17px 20px;border-bottom:1px solid #f3f4f6;display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap}.budget-page .budget-card-header h2,.budget-page .budget-card-header h3{font-size:14px;font-weight:700;color:#1f2937;margin:0}.budget-page .budget-card-body{padding:20px}.budget-page .budget-subtitle{font-size:11.5px;color:#6b7280;margin:5px 0 0}.budget-page .budget-toolbar{display:flex;gap:12px;align-items:flex-end;flex-wrap:wrap}.budget-page .budget-toolbar .budget-field{min-width:150px;flex:1}.budget-page .budget-field{margin-bottom:16px;min-width:0}.budget-page .budget-toolbar .budget-field{margin-bottom:0}
.budget-page label{display:block;margin:0 0 7px;color:#4b5563;font-size:12px;font-weight:600}.budget-page .budget-input{display:block;width:100%;min-height:40px;background:#fff;border:1px solid #d1d5db!important;border-radius:8px;padding:9px 11px;font:inherit;font-size:12.5px;color:#1f2937;box-shadow:none!important}.budget-page .budget-input:focus{outline:0;border-color:#8b5cf6!important;box-shadow:0 0 0 3px #ede9fe!important}.budget-page textarea.budget-input{resize:vertical;min-height:100px}.budget-page .budget-help{font-size:11px;color:#6b7280;margin:7px 0 0;line-height:1.6}
.budget-page .budget-note{display:flex;align-items:flex-start;gap:10px;padding:13px 16px;border-radius:10px;background:#f5f3ff;color:#5b21b6;border:1px solid #ede9fe;font-size:12px;line-height:1.65;margin-bottom:1.25rem}.budget-page .budget-note i{margin-top:3px}.budget-page .budget-note.success{background:#ecfdf5;color:#065f46;border-color:#a7f3d0}.budget-page .budget-note.danger{background:#fef2f2;color:#991b1b;border-color:#fecaca}.budget-page .budget-note ul{margin:0;padding-left:18px}
.budget-page .budget-table-wrap{overflow-x:auto}.budget-page .budget-table{width:100%;border-collapse:collapse;font-size:12.5px;margin:0}.budget-page .budget-table th{padding:12px 18px;background:#f9fafb;color:#6b7280;text-transform:uppercase;letter-spacing:.04em;font-size:10.5px;font-weight:700;white-space:nowrap;border-bottom:1px solid var(--budget-line);text-align:left}.budget-page .budget-table td{padding:15px 18px;border-bottom:1px solid #f3f4f6;vertical-align:middle}.budget-page .budget-table tr:last-child td{border-bottom:0}.budget-page .budget-table tbody tr:hover{background:#faf8ff}.budget-page .budget-money{white-space:nowrap;font-variant-numeric:tabular-nums;font-weight:600;color:#1f2937}.budget-page .budget-positive{color:#047857}.budget-page .budget-negative{color:#b91c1c}.budget-page .budget-department{display:flex;align-items:center;gap:10px;font-weight:700;color:#374151}.budget-page .budget-icon{width:34px;height:34px;background:#f5f3ff;color:#7c3aed;border-radius:9px;display:inline-flex;align-items:center;justify-content:center;flex-shrink:0}
.budget-page .budget-edit{display:flex;gap:7px;align-items:center;min-width:215px}.budget-page .budget-edit .budget-input{min-width:120px}.budget-page .budget-badge{display:inline-flex;align-items:center;gap:5px;font-size:10.5px;font-weight:700;border-radius:20px;padding:5px 10px;white-space:nowrap;line-height:1.35}.budget-page .budget-badge.purple{background:#ede9fe;color:#5b21b6}.budget-page .budget-badge.green{background:#d1fae5;color:#065f46}.budget-page .budget-badge.amber{background:#fef3c7;color:#92400e}.budget-page .budget-badge.red{background:#fee2e2;color:#991b1b}.budget-page .budget-badge.gray{background:#f3f4f6;color:#4b5563}.budget-page .budget-badge.blue{background:#dbeafe;color:#1e40af}
.budget-page .budget-progress{height:5px;background:#f3f4f6;border-radius:8px;overflow:hidden;width:110px;margin-top:7px}.budget-page .budget-progress span{display:block;height:100%;background:#8b5cf6;border-radius:8px}.budget-page .budget-two-col{display:grid;grid-template-columns:minmax(0,1.6fr) minmax(240px,1fr);gap:20px}.budget-page .budget-guide{list-style:none;padding:0;margin:0}.budget-page .budget-guide li{display:flex;gap:11px;margin-bottom:18px;align-items:flex-start}.budget-page .budget-guide li:last-child{margin-bottom:0}.budget-page .budget-step-number{width:26px;height:26px;border-radius:50%;background:#ede9fe;color:#5b21b6;font-weight:700;font-size:12px;display:inline-flex;align-items:center;justify-content:center;flex-shrink:0}.budget-page .budget-guide strong{font-size:12px;display:block;margin-bottom:3px}.budget-page .budget-guide p{color:#6b7280;font-size:11.5px;margin:0;line-height:1.65}
.budget-page .budget-request-title{display:flex;align-items:center;gap:8px;flex-wrap:wrap}.budget-page .budget-request-amount{font-size:21px;font-weight:700;color:#4c1d95;margin-bottom:14px;font-variant-numeric:tabular-nums}.budget-page .budget-reason{font-size:12.5px;line-height:1.8;white-space:pre-line;overflow-wrap:anywhere;margin:0 0 20px}.budget-page .budget-approval-track{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px;list-style:none;padding:0;margin:0 0 18px}.budget-page .budget-approval-step{background:#f9fafb;border:1px solid #e5e7eb;border-radius:10px;padding:12px;min-width:0}.budget-page .budget-approval-step.approved{border-color:#a7f3d0;background:#f0fdf4}.budget-page .budget-approval-step.current{border-color:#c4b5fd;background:#faf8ff}.budget-page .budget-approval-step.rejected{border-color:#fecaca;background:#fef2f2}.budget-page .budget-approval-step strong{display:block;font-size:11.5px;margin:8px 0 4px}.budget-page .budget-approval-step p{font-size:11px;color:#6b7280;margin:0;overflow-wrap:anywhere}.budget-page .budget-actions{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.budget-page .budget-section-title{font-size:14px;font-weight:700;margin:0 0 15px;color:#374151}.budget-page .budget-divider{border:0;border-top:1px solid #e5e7eb;margin:20px 0}.budget-page .budget-empty{text-align:center;padding:38px 20px;color:#6b7280}.budget-page .budget-empty .budget-icon{width:50px;height:50px;margin-bottom:12px;font-size:22px}.budget-page .budget-empty h3{font-size:14px;margin:0 0 7px;color:#374151}.budget-page .budget-empty p{margin:0;font-size:12px;line-height:1.7}
.budget-page .budget-pagination{padding:14px 20px;border-top:1px solid #f3f4f6;color:#6b7280;font-size:12px}.budget-page .budget-pagination .pagination{gap:4px;flex-wrap:wrap;margin:0}.budget-page .budget-pagination .page-link{border:1px solid #e5e7eb;border-radius:7px!important;color:#5b21b6;font-size:12px;padding:6px 11px}.budget-page .budget-pagination .page-item.active .page-link{background:#7c3aed;color:#fff;border-color:#7c3aed}.budget-page .budget-details summary{color:#7c3aed;font-size:12px;font-weight:700;cursor:pointer;padding:5px 0}.budget-page .budget-details-panel{margin-top:12px;padding:14px;border:1px solid #ede9fe;border-radius:10px;background:#faf8ff;max-width:560px;min-width:260px}.budget-page .budget-change{display:grid;grid-template-columns:1fr 1fr;gap:12px}.budget-page .budget-change dt{color:#6b7280;font-size:11px;font-weight:600;margin:10px 0 3px}.budget-page .budget-change dd{font-size:12px;color:#374151;margin:0;overflow-wrap:anywhere;white-space:pre-wrap}.budget-page .budget-time{white-space:nowrap;font-size:12px}.budget-page .budget-time small{display:block;color:#9ca3af;font-size:11px;margin-top:3px}
@media(max-width:991px){.budget-page .budget-two-col{grid-template-columns:1fr}.budget-page .budget-stats{grid-template-columns:repeat(2,minmax(0,1fr))}.budget-page .budget-approval-track{gap:7px}}
@media(max-width:575px){.budget-page{padding:.5rem 0 2rem}.budget-page .budget-topbar{padding:17px}.budget-page .budget-topbar h1{font-size:16px}.budget-page .budget-stat{padding:12px}.budget-page .budget-stat-value{font-size:15px}.budget-page .budget-stats{gap:9px}.budget-page .budget-card-header,.budget-page .budget-card-body{padding:16px}.budget-page .budget-toolbar{width:100%}.budget-page .budget-toolbar .budget-field{min-width:110px}.budget-page .budget-approval-track{grid-template-columns:1fr}.budget-page .budget-approval-step{display:grid;grid-template-columns:1fr auto;column-gap:10px}.budget-page .budget-approval-step .budget-badge{grid-column:2;grid-row:1 / 3;align-self:center}.budget-page .budget-approval-step strong{margin:0 0 5px}.budget-page .budget-approval-step p{grid-column:1}.budget-page .budget-table td,.budget-page .budget-table th{padding:12px}.budget-page .budget-details-panel{min-width:220px}.budget-page .budget-change{grid-template-columns:1fr}}
</style>
